type Lang = 'ar' | 'en';
type Product = { id: number; name: string; designer: string; category: string; size: string; condition: string; conditionNotes: string; price: number; original: number; image: string; gallery: string[]; fabric: string; color: string; details: string; visible?: boolean; soldOut?: boolean };
type CartLine = { product: Product; quantity: number };
type User = { id: number; name: string; phone: string; email: string; address: string; orders: number[]; submissions: number[] };
type SubmissionStatus = 'Pending Review' | 'Approved' | 'Rejected' | 'Listed' | 'Sold';
