function readSaved<T>(key: string, fallback: T): T { try { const value = localStorage.getItem(key); return value ? JSON.parse(value) as T : fallback; } catch { return fallback; } }
const copy = (lang: Lang, ar: ReactNode, en: ReactNode): any => lang === 'ar' ? ar : en;
const priceFor = (value: number, lang: Lang) => lang === 'ar' ? `${new Intl.NumberFormat('ar-IQ').format(value * 1650)} د.ع` : `$${value.toLocaleString('en-US')}`;
const displayName = (product: Product, lang: Lang) => lang === 'ar' ? (namesAr[product.id] || product.name) : product.name;
const displayCategory = (category: string, lang: Lang) => lang === 'ar' ? (catAr[category] || category) : category;
const displayCondition = (condition: string, lang: Lang) => lang === 'ar' ? (conditionAr[condition] || condition) : condition;

function App() {
  const [route, setRoute] = useState(window.location.pathname);
  const [lang, setLang] = useState<Lang>(() => readSaved('sl-language', 'ar'));
  const [products, setProducts] = useState<Product[]>(() => readSaved('sl-products', seedProducts));
  const [submissions, setSubmissions] = useState<Submission[]>(() => readSaved('sl-submissions', seedSubmissions));
  const [users, setUsers] = useState<User[]>(() => readSaved('sl-users', seedUsers));
  const [orders, setOrders] = useState<Order[]>(() => readSaved('sl-orders', seedOrders));
  const [user, setUser] = useState<User | null>(() => readSaved('sl-user', null));
  const [admin, setAdmin] = useState(() => readSaved('sl-admin', false));
  const [adminDark, setAdminDark] = useState(() => readSaved('sl-admin-dark', false));
  const [category, setCategory] = useState('All pieces'); const [sort, setSort] = useState('Just in'); const [query, setQuery] = useState('');
  const [selected, setSelected] = useState<Product | null>(null); const [selectedImage, setSelectedImage] = useState(0);
  const [wishlist, setWishlist] = useState<number[]>([]); const [cart, setCart] = useState<CartLine[]>(() => readSaved('sl-cart', []));
  const [cartOpen, setCartOpen] = useState(false); const [checkout, setCheckout] = useState(false); const [orderComplete, setOrderComplete] = useState(false);
  const [sellOpen, setSellOpen] = useState(false); const [sellStep, setSellStep] = useState(1); const [sellSubmitted, setSellSubmitted] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false); const [authOpen, setAuthOpen] = useState(false); const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signin');
  const [authStep, setAuthStep] = useState<'phone' | 'otp' | 'profile'>('phone'); const [authPhone, setAuthPhone] = useState(''); const [authOtp, setAuthOtp] = useState(''); const [authTimer, setAuthTimer] = useState(28);
  const [profileForm, setProfileForm] = useState({ name: '', email: '', address: '' }); const [toast, setToast] = useState(''); const [formError, setFormError] = useState('');
  const [activeSection, setActiveSection] = useState<'Overview' | 'Seller Submissions' | 'Catalog' | 'Orders' | 'Users'>('Overview');
  const [adminLogin, setAdminLogin] = useState({ username: '', password: '' }); const [adminError, setAdminError] = useState('');
  const [reviewing, setReviewing] = useState<Submission | null>(null); const [reviewPrice, setReviewPrice] = useState(''); const [rejectReason, setRejectReason] = useState(''); const [catalogDraft, setCatalogDraft] = useState<Product | null>(null); const [userDetail, setUserDetail] = useState<User | null>(null); const [orderDetail, setOrderDetail] = useState<Order | null>(null);
  const [checkoutForm, setCheckoutForm] = useState({ name: '', email: '', address: '', city: '', postcode: '' });
  const [sellForm, setSellForm] = useState({ designer: '', item: 'Evening gown', size: '', notes: '', email: '', payout: 'Bank transfer', files: '' });
  const [stylistOpen, setStylistOpen] = useState(false); const [stylistInput, setStylistInput] = useState(''); const [stylistMessages, setStylistMessages] = useState<{ role: 'assistant' | 'user'; text: string }[]>([]);

  useEffect(() => { const onPop = () => setRoute(window.location.pathname); window.addEventListener('popstate', onPop); return () => window.removeEventListener('popstate', onPop); }, []);
  useEffect(() => { document.documentElement.lang = lang === 'ar' ? 'ar-IQ' : 'en'; document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr'; localStorage.setItem('sl-language', lang); }, [lang]);
  useEffect(() => { localStorage.setItem('sl-products', JSON.stringify(products)); }, [products]); useEffect(() => { localStorage.setItem('sl-submissions', JSON.stringify(submissions)); }, [submissions]); useEffect(() => { localStorage.setItem('sl-users', JSON.stringify(users)); }, [users]); useEffect(() => { localStorage.setItem('sl-orders', JSON.stringify(orders)); }, [orders]); useEffect(() => { localStorage.setItem('sl-user', JSON.stringify(user)); }, [user]); useEffect(() => { localStorage.setItem('sl-admin', JSON.stringify(admin)); }, [admin]); useEffect(() => { localStorage.setItem('sl-cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { if (!authOpen || authStep !== 'otp' || authTimer <= 0) return; const timer = window.setInterval(() => setAuthTimer((v) => Math.max(v - 1, 0)), 1000); return () => window.clearInterval(timer); }, [authOpen, authStep, authTimer]);
  const navigate = (next: string) => { window.history.pushState({}, '', next); setRoute(next); window.scrollTo(0, 0); };
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2600); };
  const scrollTo = (id: string) => document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
  const filtered = useMemo(() => { const q = query.trim().toLowerCase(); const list = products.filter((p) => p.visible !== false && !p.soldOut && (category === 'All pieces' || p.category === category) && (!q || `${p.name} ${p.designer} ${p.category} ${p.color}`.toLowerCase().includes(q))); return sort === 'Price: low to high' ? [...list].sort((a, b) => a.price - b.price) : sort === 'Price: high to low' ? [...list].sort((a, b) => b.price - a.price) : list; }, [products, category, sort, query]);
  const cartCount = cart.reduce((sum, line) => sum + line.quantity, 0); const subtotal = cart.reduce((sum, line) => sum + line.product.price * line.quantity, 0);
  const closeOverlays = () => { setCartOpen(false); setSelected(null); setSellOpen(false); setAuthOpen(false); };
  const addToCart = (product: Product) => { setCart((lines) => lines.some((l) => l.product.id === product.id) ? lines.map((l) => l.product.id === product.id ? { ...l, quantity: l.quantity + 1 } : l) : [...lines, { product, quantity: 1 }]); notify(copy(lang, 'تمت إضافة القطعة إلى حقيبتك', `${product.name} added to your edit`)); };
  const beginSell = () => { setSellOpen(true); setSellStep(1); setSellSubmitted(false); setFormError(''); };
  const openAuth = (mode: 'signin' | 'signup' = 'signin') => { setAuthMode(mode); setAuthStep('phone'); setAuthPhone(''); setAuthOtp(''); setAuthTimer(28); setFormError(''); setAuthOpen(true); };
  const submitSell = () => { const id = Math.max(0, ...submissions.map((s) => s.id)) + 1; const entry: Submission = { id, ...sellForm, status: 'Pending Review', requestedPayout: Math.round(150 + Math.random() * 160), sellerPhone: user?.phone }; setSubmissions((items) => [entry, ...items]); if (user) { const updated = { ...user, submissions: [...user.submissions, id] }; setUser(updated); setUsers((items) => items.map((u) => u.id === user.id ? updated : u)); } setSellSubmitted(true); };
  const completeOrder = () => { if (Object.values(checkoutForm).some((v) => !v.trim())) { setFormError(copy(lang, 'يرجى إكمال معلومات التوصيل.', 'Please complete each delivery detail.')); return; } const id = Math.max(1000, ...orders.map((o) => o.id)) + 1; const newOrder: Order = { id, userId: user?.id, customer: checkoutForm.name, phone: user?.phone || '+964', email: checkoutForm.email, address: `${checkoutForm.address}, ${checkoutForm.city}, ${checkoutForm.postcode}`, items: cart, total: subtotal, status: 'Processing', date: copy(lang, 'اليوم', 'Today') }; setOrders((items) => [newOrder, ...items]); if (user) { const updated = { ...user, name: user.name || checkoutForm.name, email: checkoutForm.email, address: newOrder.address, orders: [...user.orders, id] }; setUser(updated); setUsers((items) => items.map((u) => u.id === user.id ? updated : u)); } setFormError(''); setOrderComplete(true); };
  const answerStylist = (prompt: string) => { const lower = prompt.toLowerCase(); const answer = lang === 'ar' ? lower.includes('مقاس') || lower.includes('قياس') ? 'للمقاس الأدق، اختاري مقاسك المعتاد وراجعي تفاصيل القطعة. هذه المجموعة مختارة بمقاسات UK، ويمكنني اقتراح البديل الأقرب.' : lower.includes('لون') || lower.includes('زفاف') || lower.includes('حنة') ? 'لليلة حنّة أو زفاف، أقترح الشمبانيا أو الزمرد؛ ألوان غنية تظهر beautifully في إضاءة القاعات وتبقى أنيقة في الصور.' : lower.includes('حالة') || lower.includes('أصلي') || lower.includes('أصالة') ? 'كل قطعة تمر بمراجعة أصالة وفحص دقيق. ستجدين ملاحظات الحالة، تفاصيل الخامة، والملصق الأصلي داخل صفحة كل قطعة.' : 'أفهم المناسبة. أخبريني بالمقاس واللون الذي تحبينه، وسأضيّق الاختيار من المجموعة الحالية.' : lower.includes('size') ? 'Choose your usual UK size first. Each listing includes its exact fit and condition notes, and I can help compare a nearby option.' : lower.includes('colour') || lower.includes('color') || lower.includes('wedding') || lower.includes('henna') ? 'For a wedding or henna night, I would start with champagne or emerald: luminous in ballroom light, distinctive in photographs.' : lower.includes('condition') || lower.includes('authentic') ? 'Every active piece is reviewed for authenticity and inspected by our team. The listing records fabric, label and any visible wear.' : 'Tell me the occasion, your usual UK size, and a colour you love. I will narrow the active edit for you.'; setStylistMessages((messages) => [...messages, { role: 'user', text: prompt }, { role: 'assistant', text: answer }]); setStylistInput(''); };

  if (route === '/admin/login') return <AdminLogin lang={lang} setLang={setLang} adminLogin={adminLogin} setAdminLogin={setAdminLogin} error={adminError} setError={setAdminError} onSuccess={() => { setAdmin(true); navigate('/admin/dashboard'); }} onBack={() => navigate('/')} />;
  if (route === '/admin/dashboard' && !admin) return <AdminLogin lang={lang} setLang={setLang} adminLogin={adminLogin} setAdminLogin={setAdminLogin} error={adminError} setError={setAdminError} onSuccess={() => { setAdmin(true); navigate('/admin/dashboard'); }} onBack={() => navigate('/')} />;
  if (route === '/admin/dashboard') return <AdminDashboard lang={lang} setLang={setLang} dark={adminDark} setDark={setAdminDark} active={activeSection} setActive={setActiveSection} submissions={submissions} setSubmissions={setSubmissions} products={products} setProducts={setProducts} orders={orders} setOrders={setOrders} users={users} reviewing={reviewing} setReviewing={setReviewing} reviewPrice={reviewPrice} setReviewPrice={setReviewPrice} rejectReason={rejectReason} setRejectReason={setRejectReason} draft={catalogDraft} setDraft={setCatalogDraft} userDetail={userDetail} setUserDetail={setUserDetail} orderDetail={orderDetail} setOrderDetail={setOrderDetail} notify={notify} onLogout={() => { setAdmin(false); navigate('/'); }} />;

  return <div className={`sl-root ${lang === 'ar' ? 'is-ar lang-ar' : 'lang-en'}`}>
    <div className="sl-top">{copy(lang, 'توصيل مجاني داخل العراق للطلبات فوق ٤١٢,٥٠٠ د.ع · طريقة أرقى لارتداء المناسبات', 'Complimentary delivery on edits over $250 · A more considered way to dress')}</div>
    <nav className="sl-nav"><button className="sl-mobile" aria-label={copy(lang, 'فتح القائمة', 'Open menu')} onClick={() => setMenuOpen(!menuOpen)}><Menu size={20} /></button><button className="sl-logo" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>second life<em>.</em></button><div className="sl-navlinks"><button onClick={() => scrollTo('shop')}>{copy(lang, 'المجموعة', 'The edit')}</button><button onClick={beginSell}>{copy(lang, 'بيعي معنا', 'Sell with us')}</button><button onClick={() => scrollTo('story')}>{copy(lang, 'معيارنا', 'Our standard')}</button></div><div className="sl-actions"><button className="lang-switch" onClick={() => setLang(lang === 'ar' ? 'en' : 'ar')}><span className={lang === 'ar' ? 'active' : ''}>العربية</span><i>|</i><span className={lang === 'en' ? 'active' : ''}>EN</span></button>{user ? <button className="sl-auth-trigger" onClick={() => notify(copy(lang, `لديك ${user.orders.length} طلبات و${user.submissions.length} قطع معروضة`, `${user.orders.length} purchases · ${user.submissions.length} submissions`))}><span className="sl-avatar">{user.name.slice(0, 1)}</span><span className="sl-auth-name">{user.name.split(' ')[0]}</span></button> : <button className="sl-auth-trigger" onClick={() => openAuth()}><UserRound size={16} /><span>{copy(lang, 'دخول', 'Sign in')}</span></button>}<button className="sl-icon" aria-label={copy(lang, 'البحث', 'Search')} onClick={() => { const el = document.querySelector('.sl-search input') as HTMLInputElement | null; el?.focus(); }}><Search size={18} /></button><button className="sl-icon" aria-label={copy(lang, 'فتح الحقيبة', 'Open edit')} onClick={() => setCartOpen(true)}><ShoppingBag size={19} />{cartCount > 0 && <span className="sl-count">{cartCount}</span>}</button></div>{menuOpen && <div className="sl-mobile-menu"><button onClick={() => { scrollTo('shop'); setMenuOpen(false); }}>{copy(lang, 'تصفحي المجموعة', 'Shop the edit')}</button><button onClick={() => { beginSell(); setMenuOpen(false); }}>{copy(lang, 'بيعي معنا', 'Sell with us')}</button><button onClick={() => { scrollTo('story'); setMenuOpen(false); }}>{copy(lang, 'معيارنا', 'Our standard')}</button></div>}</nav>
    <div className="sl-search"><Search size={15} /><input type="search" value={query} onChange={(e) => { setQuery(e.target.value); scrollTo('shop'); }} placeholder={copy(lang, 'ابحثي عن مصمم أو لون أو مناسبة', 'Search designer, colour or occasion')} /><X size={15} onClick={() => setQuery('')} /></div>
    <main><section className="sl-hero"><div className="sl-hero-copy"><div className="sl-eyebrow">{copy(lang, 'اختيارات مناسبة مدروسة · ٠١ / ٠٤', 'The considered occasion edit · 01 / 04')}</div><h1>{copy(lang, <>امنحي الفخامة<br /><i>حياةً ثانية.</i></>, <>Give luxury<br /><i>a second life.</i></>)}</h1><p>{copy(lang, 'أزياء مناسبات مستعملة بحالة راقية، موثّقة ومفحوصة وجاهزة لفصلها القادم.', 'Pre-owned formalwear with a past worth knowing — authenticated, inspected, and ready for the next chapter.')}</p><div className="sl-hero-actions"><button className="sl-btn" onClick={() => scrollTo('shop')}>{copy(lang, 'تصفحي المجموعة', 'Shop the edit')} <ArrowRight size={14} /></button><button className="sl-btn alt" onClick={beginSell}>{copy(lang, 'بيعي فستانك', 'Sell your dress')}</button></div></div><div className="sl-hero-img"><div className="sl-hero-tag">{copy(lang, 'الفستان ليس قصة واحدة.', 'A dress is never just one story.')}</div></div></section>
      <section className="sl-section occasion-section"><div className="sl-section-head"><div><div className="sl-eyebrow">{copy(lang, 'مصممة لليالي العراقية', 'Chosen for the nights that matter')}</div><h2>{copy(lang, 'اختاري مناسبتك', 'Find your occasion')}</h2></div><p>{copy(lang, 'قطع بحضور خاص، للمناسبات التي تستحق أكثر من ارتداء واحد.', 'Pieces with presence, chosen for the moments that deserve more than one wear.')}</p></div><div className="sl-cats">{categories.map((item, index) => <button className="sl-cat" key={item} onClick={() => { setCategory(item); scrollTo('shop'); }}><small>0{index + 1}</small><span>{displayCategory(item, lang)}</span><ArrowUpRight /></button>)}</div></section>
      <section className="sl-section" id="shop"><div className="sl-section-head"><div><div className="sl-eyebrow">{copy(lang, 'وصلت حديثاً', 'A fresh arrival, always')}</div><h2>{copy(lang, 'المجموعة الحالية', 'Just in')}</h2></div><div className="sl-tools"><select value={category} onChange={(e) => setCategory(e.target.value)}><option value="All pieces">{copy(lang, 'كل القطع', 'All pieces')}</option>{categories.map((item) => <option key={item} value={item}>{displayCategory(item, lang)}</option>)}</select><select value={sort} onChange={(e) => setSort(e.target.value)}><option value="Just in">{copy(lang, 'الأحدث', 'Just in')}</option><option value="Price: low to high">{copy(lang, 'السعر: من الأقل', 'Price: low to high')}</option><option value="Price: high to low">{copy(lang, 'السعر: من الأعلى', 'Price: high to low')}</option></select></div></div><div className="sl-grid">{filtered.map((product) => <article className="sl-product" key={product.id} onClick={() => { setSelected(product); setSelectedImage(0); }}><div className="sl-photo"><img src={asset(product.image)} alt={`${displayName(product, lang)} by ${product.designer}`} /><button className="sl-heart" aria-label={copy(lang, 'إضافة للمفضلة', 'Add to wishlist')} onClick={(e) => { e.stopPropagation(); setWishlist((items) => items.includes(product.id) ? items.filter((id) => id !== product.id) : [...items, product.id]); }}><Heart size={15} fill={wishlist.includes(product.id) ? '#b97869' : 'none'} color={wishlist.includes(product.id) ? '#b97869' : 'currentColor'} /></button><span className="sl-badge">{displayCondition(product.condition, lang)}</span></div><div className="sl-product-info"><h3>{displayName(product, lang)}</h3><p>{product.designer} · {product.size}</p><div className="sl-price"><b>{priceFor(product.price, lang)}</b><s>{priceFor(product.original, lang)}</s><span className="sl-save">{copy(lang, `وفرّي ${Math.round((1 - product.price / product.original) * 100)}٪`, `Save ${Math.round((1 - product.price / product.original) * 100)}%`)}</span></div></div></article>)}</div>{!filtered.length && <p className="sl-empty">{copy(lang, 'هذه المجموعة بين فصلين. جرّبي بحثاً أو تصنيفاً آخر.', 'This edit is between chapters. Try another search or category.')}</p>}</section>
      <section className="sl-trust" id="story"><div><div className="sl-eyebrow">{copy(lang, 'لماذا second life', 'Why second life')}</div><h2>{copy(lang, <>أفضل<br /><i>للفستان.</i></>, <>Better for<br /><i>the dress.</i></>)}</h2></div><div className="sl-trust-grid"><Trust icon={<ShieldCheck size={22} />} title={copy(lang, 'موثّقة', 'Authenticated')} text={copy(lang, 'كل قطعة تمر بمراجعة خبرائنا قبل أن تجد مكانها هنا.', 'Every piece is reviewed by our in-house specialists before it earns its place here.')} /><Trust icon={<Sparkles size={22} />} title={copy(lang, 'مفحوصة', 'Inspected')} text={copy(lang, 'نوثّق كل تفصيل، من ملمس الخامة إلى أصغر علامة ارتداء.', 'We document every detail, from the hand of the fabric to the smallest sign of wear.')} /><Trust icon={<RotateCcw size={22} />} title={copy(lang, 'في دورة جديدة', 'In circulation')} text={copy(lang, 'طريقة أجمل لتقليل أثر أزياء المناسبات، إطلالة بعد أخرى.', 'A more beautiful way to reduce the impact of occasion dressing, one wear at a time.')} /></div></section>
      <section className="sl-sell" id="sell"><div><div className="sl-eyebrow">{copy(lang, 'خزانة مستمرة', 'Your wardrobe, continued')}</div><h2>{copy(lang, <>دعي شخصاً<br /><i>يعيش اللحظة.</i></>, <>Let someone<br /><i>have the moment.</i></>)}</h2><p>{copy(lang, 'نجعل بيع قطعك الخاصة مدروساً مثل شرائها. نتولى التفاصيل، وتحصلين على عائدك.', 'We make selling your special pieces as thoughtful as buying them. Our team handles the details; you receive the return.')}</p><button className="sl-btn" onClick={beginSell}>{copy(lang, 'ابدئي البيع', 'Start selling')} <ArrowRight size={14} /></button></div><div className="sl-sell-card"><div className="sl-eyebrow">{copy(lang, 'وعد Second Life', 'The Second Life promise')}</div><h3>{copy(lang, 'قطعة أقل في آخر الخزانة.', 'One less dress in the back of the wardrobe.')}</h3><p>{copy(lang, 'انضمي إلى ١,٨٤٠ امرأة يمنحن قطعهن أمسية أخرى لا تُنسى.', 'Join 1,840 women giving their best pieces another evening to remember.')}</p><div className="sl-sell-stat"><span>{copy(lang, 'متوسط عائد البائعة', 'Average seller return')}</span><b>{priceFor(186, lang)}</b></div></div></section></main>
    <footer className="sl-footer"><div className="sl-logo">second life<em>.</em></div><div>{copy(lang, 'أناقة هادئة. دائماً مدروسة.', 'Quietly glamorous. Considered always.')}</div><div className="sl-mono">{copy(lang, 'بغداد · العراق', 'Baghdad · Iraq')} <button onClick={() => navigate('/admin/login')}>{copy(lang, 'دخول الإدارة', 'Admin login')}</button></div></footer>
    <button className={`stylist-launcher ${stylistOpen ? 'is-open' : ''}`} onClick={() => setStylistOpen(!stylistOpen)}><Sparkles size={18} /><span>{copy(lang, 'مساعدة المنسقة', 'AI Stylist')}</span></button>
    {stylistOpen && <Stylist lang={lang} messages={stylistMessages} input={stylistInput} setInput={setStylistInput} submit={answerStylist} products={products.filter((p) => p.visible !== false && !p.soldOut)} openProduct={(p) => { setSelected(p); setStylistOpen(false); }} addToCart={addToCart} />}
    {(cartOpen || selected || sellOpen || authOpen) && <div className="sl-overlay" onClick={closeOverlays} />}
    {selected && <ProductDialog lang={lang} selected={selected} selectedImage={selectedImage} setSelectedImage={setSelectedImage} close={() => setSelected(null)} addToCart={addToCart} notify={notify} />}
    {cartOpen && <CartDrawer lang={lang} cart={cart} cartCount={cartCount} subtotal={subtotal} checkout={checkout} setCheckout={setCheckout} orderComplete={orderComplete} checkoutForm={checkoutForm} setCheckoutForm={setCheckoutForm} formError={formError} completeOrder={completeOrder} changeQuantity={(id, delta) => setCart((lines) => lines.flatMap((l) => l.product.id !== id ? [l] : l.quantity + delta > 0 ? [{ ...l, quantity: l.quantity + delta }] : []))} close={() => setCartOpen(false)} setOrderComplete={setOrderComplete} setCart={setCart} scrollTo={scrollTo} />}
    {sellOpen && <SellDialog lang={lang} submitted={sellSubmitted} step={sellStep} setStep={setSellStep} form={sellForm} setForm={setSellForm} error={formError} setError={setFormError} submit={submitSell} close={() => setSellOpen(false)} />}
    {authOpen && <AuthModal lang={lang} mode={authMode} setMode={setAuthMode} step={authStep} setStep={setAuthStep} phone={authPhone} setPhone={setAuthPhone} otp={authOtp} setOtp={setAuthOtp} timer={authTimer} setTimer={setAuthTimer} profile={profileForm} setProfile={setProfileForm} error={formError} setError={setFormError} close={() => setAuthOpen(false)} complete={(newUser) => { setUser(newUser); setUsers((items) => items.some((u) => u.phone === newUser.phone) ? items.map((u) => u.phone === newUser.phone ? newUser : u) : [newUser, ...items]); setAuthOpen(false); notify(copy(lang, `أهلاً بكِ ${newUser.name.split(' ')[0]}`, `Welcome to Second Life, ${newUser.name.split(' ')[0]}`)); }} />}
    {toast && <div className="sl-toast">{toast}</div>}
  </div>;
}

function Trust({ icon, title, text }: { icon: ReactNode; title: string; text: string }) { return <div className="sl-trust-item">{icon}<h3>{title}</h3><p>{text}</p></div>; }
function ProductDialog({ lang, selected, selectedImage, setSelectedImage, close, addToCart, notify }: { lang: Lang; selected: Product; selectedImage: number; setSelectedImage: (n: number) => void; close: () => void; addToCart: (p: Product) => void; notify: (s: string) => void }) {
  return <div className="sl-dialog" role="dialog"><button className="sl-close" onClick={close}><X /></button><div className="sl-detail"><div><img className="sl-detail-img" src={asset(selected.gallery[selectedImage])} alt="" /><div className="sl-thumbs">{selected.gallery.map((image, i) => <button key={image} className={selectedImage === i ? 'active' : ''} onClick={() => setSelectedImage(i)}><img src={asset(image)} alt="" /></button>)}</div></div><div className="sl-detail-copy"><div className="sl-eyebrow">{displayCategory(selected.category, lang)} · {displayCondition(selected.condition, lang)}</div><h2>{displayName(selected, lang)}</h2><p>{selected.designer}</p><div className="sl-price large"><b>{priceFor(selected.price, lang)}</b><s>{priceFor(selected.original, lang)}</s></div><p className="sl-detail-description">{copy(lang, 'قطعة لافتة بهدوء، عاشت حياة من قبل وجاهزة لصنع حضور جديد. مفحوصة بعناية.', 'A quietly striking piece with a life already lived. Professionally inspected and ready to make an entrance.')}</p><div className="sl-mono">{copy(lang, 'المقاس المتاح', 'Available size')}</div><div className="sl-size"><button className="active">{selected.size}</button><button onClick={() => notify(copy(lang, 'دليل المقاسات قريباً', 'Our size guide is coming soon'))}>{copy(lang, 'دليل المقاسات', 'Size guide')}</button></div><div className="sl-detail-actions"><button className="sl-btn" onClick={() => { addToCart(selected); close(); }}>{copy(lang, 'أضيفي إلى الحقيبة', 'Add to your edit')} <ShoppingBag size={14} /></button><button className="sl-btn alt" onClick={() => { addToCart(selected); close(); }}>{copy(lang, 'اشتري الآن', 'Buy now')} <ArrowRight size={14} /></button></div><div className="sl-detail-meta"><b>{copy(lang, 'التفاصيل', 'Details')}</b><br />{selected.fabric} · {selected.details}<br />{copy(lang, 'ملاحظات الحالة: ', 'Condition notes: ')}{selected.conditionNotes}</div></div></div></div>;
}
function CartDrawer({ lang, cart, cartCount, subtotal, checkout, setCheckout, orderComplete, checkoutForm, setCheckoutForm, formError, completeOrder, changeQuantity, close, setOrderComplete, setCart, scrollTo }: { lang: Lang; cart: CartLine[]; cartCount: number; subtotal: number; checkout: boolean; setCheckout: (v: boolean) => void; orderComplete: boolean; checkoutForm: { name: string; email: string; address: string; city: string; postcode: string }; setCheckoutForm: (v: { name: string; email: string; address: string; city: string; postcode: string }) => void; formError: string; completeOrder: () => void; changeQuantity: (id: number, delta: number) => void; close: () => void; setOrderComplete: (v: boolean) => void; setCart: (v: CartLine[]) => void; scrollTo: (id: string) => void }) {
  const field = (key: keyof typeof checkoutForm, value: string) => setCheckoutForm({ ...checkoutForm, [key]: value });
  return <aside className="sl-drawer"><button className="sl-close" onClick={close}><X /></button><div className="sl-eyebrow">{copy(lang, `حقيبتك · ${cartCount} قطع`, `Your edit · ${cartCount} pieces`)}</div><h2>{copy(lang, 'مختارة لكِ.', 'Saved for you.')}</h2>{orderComplete ? <div className="sl-success"><div className="sl-success-mark"><Check /></div><h2>{copy(lang, 'أصبحت لكِ.', 'Consider it yours.')}</h2><p>{copy(lang, 'تم تأكيد طلبك. ستصلك تفاصيل التوصيل قريباً.', 'Your order is confirmed. Your delivery details are on their way.')}</p><button className="sl-btn" onClick={() => { setOrderComplete(false); setCart([]); close(); }}>{copy(lang, 'العودة للمجموعة', 'Back to the collection')}</button></div> : checkout ? <><button className="sl-back" onClick={() => setCheckout(false)}><ArrowLeft size={16} /> {copy(lang, 'رجوع', 'Back')}</button><div className="sl-eyebrow">{copy(lang, 'التفصيل الأخير', 'The final detail')}</div><h2>{copy(lang, 'تفاصيل التوصيل.', 'Delivery details.')}</h2><form className="sl-checkout-form" onSubmit={(e) => { e.preventDefault(); completeOrder(); }}>{[['name', copy(lang, 'الاسم الكامل', 'Full name')], ['email', copy(lang, 'البريد الإلكتروني', 'Email address')], ['address', copy(lang, 'العنوان', 'Address')], ['city', copy(lang, 'المدينة', 'City')], ['postcode', copy(lang, 'الرمز البريدي', 'Postcode')]].map(([key, label]) => <label className="sl-field" key={key}>{label}<input required type={key === 'email' ? 'email' : 'text'} value={checkoutForm[key as keyof typeof checkoutForm]} onChange={(e) => field(key as keyof typeof checkoutForm, e.target.value)} /></label>)}{formError && <p className="sl-form-error">{formError}</p>}<button className="sl-btn" type="submit">{copy(lang, 'تأكيد الطلب', 'Place order')} · {priceFor(subtotal, lang)}</button></form></> : !cart.length ? <div className="sl-cart-empty"><ShoppingBag size={25} /><p>{copy(lang, 'حقيبتك تنتظر أول قطعة.', 'Your edit is waiting to be started.')}</p><button className="sl-btn" onClick={() => { close(); scrollTo('shop'); }}>{copy(lang, 'اكتشفي القطع', 'Discover pieces')}</button></div> : <>{cart.map((line) => <div className="sl-cart-row" key={line.product.id}><img src={asset(line.product.image)} alt="" /><div className="sl-cart-row-copy"><h3>{displayName(line.product, lang)}</h3><p>{line.product.designer} · {line.product.size}</p><b>{priceFor(line.product.price * line.quantity, lang)}</b><div className="sl-qty"><button onClick={() => changeQuantity(line.product.id, -1)}><Minus size={12} /></button><span>{line.quantity}</span><button onClick={() => changeQuantity(line.product.id, 1)}><Plus size={12} /></button></div></div><button className="sl-close" onClick={() => changeQuantity(line.product.id, -line.quantity)}><Trash2 size={15} /></button></div>)}<div className="sl-cart-footer"><div className="sl-cart-total"><span>{copy(lang, 'المجموع', 'Subtotal')}</span><b>{priceFor(subtotal, lang)}</b></div><p>{copy(lang, 'التوصيل داخل العراق يُحسب عند الدفع.', 'Delivery is calculated at checkout.')}</p><button className="sl-btn" onClick={() => setCheckout(true)}>{copy(lang, 'متابعة الدفع', 'Continue to checkout')} <ArrowRight size={14} /></button></div></>}</aside>;
}
function SellDialog({ lang, submitted, step, setStep, form, setForm, error, setError, submit, close }: { lang: Lang; submitted: boolean; step: number; setStep: (n: number) => void; form: { designer: string; item: string; size: string; notes: string; email: string; payout: string; files: string }; setForm: (v: typeof form) => void; error: string; setError: (v: string) => void; submit: () => void; close: () => void }) {
  const update = (key: keyof typeof form, value: string) => setForm({ ...form, [key]: value });
  return <div className="sl-dialog small"><button className="sl-close" onClick={close}><X /></button>{submitted ? <div className="sl-success"><div className="sl-success-mark"><Check /></div><h2>{copy(lang, 'وصلتنا قصتك.', 'We have your story.')}</h2><p>{copy(lang, 'سيراجع فريقنا قطعتك ويتواصل معكِ خلال يومي عمل.', 'Our specialists will review your piece and write within 2 working days.')}</p><button className="sl-btn" onClick={close}>{copy(lang, 'العودة للمجموعة', 'Back to the collection')}</button></div> : <><div className="sl-eyebrow">{copy(lang, `البيع معنا · الخطوة ${step} من 4`, `Sell with us · Step ${step} of 4`)}</div><div className="sl-progress">{[1, 2, 3, 4].map((n) => <i key={n} className={n <= step ? 'on' : ''} />)}</div>{step === 1 && <><h2>{copy(lang, <>أخبرينا عن<br /><i>قطعتك.</i></>, <>Tell us about<br /><i>your piece.</i></>)}</h2><div className="sl-form"><label className="sl-field">{copy(lang, 'المصمم', 'Designer')}<input value={form.designer} onChange={(e) => update('designer', e.target.value)} placeholder="e.g. Emilia Wickstead" /></label><label className="sl-field">{copy(lang, 'ما الذي تبيعينه؟', 'What are you selling?')}<select value={form.item} onChange={(e) => update('item', e.target.value)}><option>Evening gown</option><option>Cocktail dress</option><option>Tailored suit</option><option>Two-piece set</option></select></label><label className="sl-field">{copy(lang, 'المقاس', 'Size')}<input value={form.size} onChange={(e) => update('size', e.target.value)} placeholder="UK 10" /></label><button className="sl-btn" onClick={() => { if (!form.designer || !form.size) { setError(copy(lang, 'أضيفي المصمم والمقاس للمتابعة.', 'Add the designer and size to continue.')); return; } setError(''); setStep(2); }}>{copy(lang, 'التالي: التفاصيل', 'Next: show us the details')} <ArrowRight size={14} /></button>{error && <p className="sl-form-error">{error}</p>}</div></>}{step === 2 && <><h2>{copy(lang, <>امنحيها<br /><i>سياقاً.</i></>, <>Give it<br /><i>some context.</i></>)}</h2><div className="sl-upload"><Upload size={23} /><b>{copy(lang, 'شاركي حتى ٥ صور', 'Share up to 5 photographs')}</b><br /><span>{copy(lang, 'الأمام، الخلف، الملصق وأي تفصيل مهم', 'Front, back, label and any details we should know')}</span><input type="file" accept="image/*" multiple onChange={(e) => update('files', e.target.files?.length ? `${e.target.files.length} photos selected` : '')} /></div><label className="sl-field">{copy(lang, 'ملاحظات الحالة', 'Condition notes')}<textarea value={form.notes} onChange={(e) => update('notes', e.target.value)} /></label><div className="sl-step-actions"><button className="sl-btn alt" onClick={() => setStep(1)}><ChevronLeft size={14} /> {copy(lang, 'رجوع', 'Back')}</button><button className="sl-btn" onClick={() => setStep(3)}>{copy(lang, 'التالي', 'Next')} <ArrowRight size={14} /></button></div></>}{step === 3 && <><div className="sl-sell-icon"><CircleDollarSign size={32} /><h2>{copy(lang, 'اقتربنا.', 'Almost there.')}</h2><p>{copy(lang, 'أين نرسل عائدك عندما تجد قطعتك منزلها الجديد؟', 'Where should we send your return when your piece finds its next home?')}</p></div><label className="sl-field">{copy(lang, 'البريد الإلكتروني', 'Email address')}<input type="email" value={form.email} onChange={(e) => update('email', e.target.value)} /></label><label className="sl-field">{copy(lang, 'طريقة العائد', 'Payout preference')}<select value={form.payout} onChange={(e) => update('payout', e.target.value)}><option>Bank transfer</option><option>Store credit (+10%)</option></select></label><div className="sl-step-actions"><button className="sl-btn alt" onClick={() => setStep(2)}><ChevronLeft size={14} /> {copy(lang, 'رجوع', 'Back')}</button><button className="sl-btn" onClick={() => { if (!form.email.includes('@')) { setError(copy(lang, 'أضيفي بريداً صحيحاً.', 'Add a valid email address.')); return; } setError(''); setStep(4); }}>{copy(lang, 'مراجعة الطلب', 'Review submission')} <ArrowRight size={14} /></button></div>{error && <p className="sl-form-error">{error}</p>}</>}{step === 4 && <><h2>{copy(lang, <>جاهزة لفصلها<br /><i>القادم؟</i></>, <>Ready for its<br /><i>next chapter?</i></>)}</h2><p>{copy(lang, `سنراجع ${form.item} من ${form.designer} ونتواصل معكِ عبر ${form.email}.`, `We will review your ${form.item} by ${form.designer} and contact you at ${form.email}.`)}</p><div className="sl-review-summary"><b>{copy(lang, 'تفاصيل المراجعة', 'Details to review')}</b><br />{form.size} · {form.payout}<br />{form.files || copy(lang, 'لم تُرفق صور بعد', 'No photographs attached yet')}</div><div className="sl-step-actions"><button className="sl-btn alt" onClick={() => setStep(3)}><ChevronLeft size={14} /> {copy(lang, 'رجوع', 'Back')}</button><button className="sl-btn" onClick={submit}>{copy(lang, 'إرسال للمراجعة', 'Submit for review')} <Check size={14} /></button></div></>}</>}</div>;
}

function AuthModal({ lang, mode, setMode, step, setStep, phone, setPhone, otp, setOtp, timer, setTimer, profile, setProfile, error, setError, close, complete }: { lang: Lang; mode: 'signin' | 'signup'; setMode: (v: 'signin' | 'signup') => void; step: 'phone' | 'otp' | 'profile'; setStep: (v: 'phone' | 'otp' | 'profile') => void; phone: string; setPhone: (v: string) => void; otp: string; setOtp: (v: string) => void; timer: number; setTimer: (v: number) => void; profile: { name: string; email: string; address: string }; setProfile: (v: { name: string; email: string; address: string }) => void; error: string; setError: (v: string) => void; close: () => void; complete: (u: User) => void }) {
  const normalPhone = `+964 ${phone.replace(/\D/g, '').replace(/^964/, '').trim()}`;
  return <div className="sl-dialog auth-dialog"><button className="sl-close" onClick={close}><X /></button><div className="auth-mark">second life<em>.</em></div>{step === 'phone' && <><div className="sl-eyebrow">{copy(lang, 'حساب مدروس', 'A considered account')}</div><h2>{copy(lang, mode === 'signin' ? 'أهلاً بعودتكِ.' : 'ابدئي حياتك الثانية.', mode === 'signin' ? 'Welcome back.' : 'Begin your second life.')}</h2><p className="auth-copy">{copy(lang, 'دخلي برقم هاتفكِ. سنرسل رمزاً لمرة واحدة عبر واتساب.', 'Sign in with your phone number. We will send a one-time code through WhatsApp.')}</p><div className="auth-mode"><button className={mode === 'signin' ? 'active' : ''} onClick={() => setMode('signin')}>{copy(lang, 'دخول', 'Sign in')}</button><button className={mode === 'signup' ? 'active' : ''} onClick={() => setMode('signup')}>{copy(lang, 'حساب جديد', 'Sign up')}</button></div><label className="sl-field">{copy(lang, 'رقم الهاتف العراقي', 'Iraqi mobile number')}<div className="phone-field"><span>+964 Iraq</span><input inputMode="tel" placeholder="770 000 0000" value={phone} onChange={(e) => setPhone(e.target.value.replace(/[^0-9 ]/g, ''))} /></div></label>{error && <p className="sl-form-error">{error}</p>}<button className="sl-btn auth-submit" onClick={() => { if (phone.replace(/\D/g, '').length < 9) { setError(copy(lang, 'أدخلي رقم هاتف عراقي صحيح.', 'Enter a valid Iraqi mobile number.')); return; } setError(''); setTimer(28); setStep('otp'); }}>{copy(lang, 'إرسال رمز واتساب', 'Send WhatsApp code')} <ArrowRight size={14} /></button><p className="auth-legal">{copy(lang, 'بالمتابعة، توافقين على استلام رسالة تحقق.', 'By continuing, you agree to receive an account verification message.')}</p></>}{step === 'otp' && <><div className="sl-eyebrow">{copy(lang, 'تحقق', 'Verification')}</div><h2>{copy(lang, 'تحققي من واتساب.', 'Check WhatsApp.')}</h2><p className="auth-copy">{copy(lang, 'أرسلنا رمزاً من ستة أرقام إلى', 'A six-digit code was sent to')} <b>{normalPhone}</b>.</p><span className="whatsapp-badge"><span>WA</span>{copy(lang, 'رسالة واتساب أُرسلت', 'WhatsApp message sent')}</span><label className="sl-field otp-label">{copy(lang, 'الرمز المكوّن من ستة أرقام', 'Six-digit code')}<input autoFocus inputMode="numeric" maxLength={6} value={otp} onChange={(e) => setOtp(e.target.value.replace(/\D/g, ''))} placeholder="000000" /></label><p className="demo-hint">{copy(lang, 'للتجربة، أي ستة أرقام ستتحقق من الحساب.', 'For this demo, any six digits will verify.')}</p>{error && <p className="sl-form-error">{error}</p>}<button className="sl-btn auth-submit" onClick={() => { if (otp.length !== 6) { setError(copy(lang, 'أدخلي الأرقام الستة كاملة.', 'Enter all six digits to continue.')); return; } const saved = readSaved<User | null>('sl-user', null); if (mode === 'signin' && saved?.phone === normalPhone.replace(' ', '')) { complete(saved); return; } setError(''); setStep('profile'); }}>{copy(lang, 'تأكيد الرمز', 'Verify code')} <Check size={14} /></button><button className="resend-btn" disabled={timer > 0} onClick={() => { setTimer(28); setError(copy(lang, 'أرسلنا رمزاً جديداً.', 'A new WhatsApp code has been sent.')); }}>{timer > 0 ? `${copy(lang, 'إعادة الإرسال بعد', 'Resend in')} 00:${String(timer).padStart(2, '0')}` : copy(lang, 'إعادة إرسال الرمز', 'Resend OTP')}</button></>}{step === 'profile' && <><div className="sl-eyebrow">{copy(lang, 'تفصيل أخير', 'One final detail')}</div><h2>{copy(lang, 'اجعليه حسابكِ.', 'Make it yours.')}</h2><p className="auth-copy">{copy(lang, 'أكملي ملفكِ لتصبح تجربة الدفع والبيع أسهل.', 'Set up your profile so checkout and selling feel effortless.')}</p><label className="sl-field">{copy(lang, 'الاسم الكامل', 'Full name')}<input autoFocus value={profile.name} onChange={(e) => setProfile({ ...profile, name: e.target.value })} /></label><label className="sl-field">{copy(lang, 'البريد الإلكتروني', 'Email address')}<input type="email" value={profile.email} onChange={(e) => setProfile({ ...profile, email: e.target.value })} /></label><label className="sl-field">{copy(lang, 'عنوان التوصيل', 'Default shipping address')}<input value={profile.address} onChange={(e) => setProfile({ ...profile, address: e.target.value })} /></label>{error && <p className="sl-form-error">{error}</p>}<button className="sl-btn auth-submit" onClick={() => { if (!profile.name.trim() || !profile.address.trim()) { setError(copy(lang, 'أضيفي اسمكِ وعنوان التوصيل.', 'Add your name and default shipping address.')); return; } complete({ id: Date.now(), name: profile.name, phone: normalPhone.replace(' ', ''), email: profile.email, address: profile.address, orders: [], submissions: [] }); }}>{copy(lang, 'حفظ الملف', 'Save profile')} <ArrowRight size={14} /></button></>}</div>;
}

function Stylist({ lang, messages, input, setInput, submit, products, openProduct, addToCart }: { lang: Lang; messages: { role: 'assistant' | 'user'; text: string }[]; input: string; setInput: (v: string) => void; submit: (v: string) => void; products: Product[]; openProduct: (p: Product) => void; addToCart: (p: Product) => void }) {
  const chips = lang === 'ar' ? ['ماذا يناسب مقاسي؟', 'اقتراح لليلة حنّة', 'كيف أتأكد من الأصالة؟'] : ['What suits my size?', 'Suggest a henna look', 'How is authenticity checked?'];
  return <aside className="stylist-panel"><div className="stylist-head"><div><div className="stylist-title"><Sparkles size={17} />{copy(lang, 'منسقتكِ الخاصة', 'Your personal stylist')}</div><span className="online-dot" /> {copy(lang, 'متاحة الآن', 'Online now')}</div><X size={17} onClick={() => document.querySelector('.stylist-launcher')?.dispatchEvent(new MouseEvent('click', { bubbles: true }))} /></div><div className="stylist-messages">{!messages.length && <div className="stylist-welcome"><b>{copy(lang, 'مساء الأناقة.', 'An evening, considered.')}</b><p>{copy(lang, 'أخبريني بالمناسبة، المقاس أو اللون. سأبحث في المجموعة الحالية.', 'Tell me the occasion, size or colour. I will search the active edit.')}</p></div>}{messages.map((message, i) => <div key={i} className={`stylist-message ${message.role}`}>{message.text}</div>)}{products.length > 0 && <div className="stylist-products">{products.slice(0, 2).map((product) => <div className="stylist-product" key={product.id}><img src={asset(product.image)} alt="" /><div><b>{displayName(product, lang)}</b><small>{priceFor(product.price, lang)}</small><div><button onClick={() => openProduct(product)}>{copy(lang, 'عرض', 'View')}</button><button onClick={() => addToCart(product)}><ShoppingBag size={12} />{copy(lang, 'أضيفي', 'Add')}</button></div></div></div>)}</div>}</div><div className="stylist-chips">{chips.map((chip) => <button key={chip} onClick={() => submit(chip)}>{chip}</button>)}</div><form className="stylist-form" onSubmit={(e) => { e.preventDefault(); if (input.trim()) submit(input.trim()); }}><input value={input} onChange={(e) => setInput(e.target.value)} placeholder={copy(lang, 'اكتبي سؤالكِ هنا', 'Ask your stylist')} /><button aria-label={copy(lang, 'إرسال', 'Send')}><Send size={15} /></button></form></aside>;
}

function LangSwitch({ lang, setLang }: { lang: Lang; setLang: (v: Lang) => void }) { return <button className="lang-switch admin-lang" onClick={() => setLang(lang === 'ar' ? 'en' : 'ar')}><span className={lang === 'ar' ? 'active' : ''}>العربية</span><i>|</i><span className={lang === 'en' ? 'active' : ''}>EN</span></button>; }
function AdminLogin({ lang, setLang, adminLogin, setAdminLogin, error, setError, onSuccess, onBack }: { lang: Lang; setLang: (v: Lang) => void; adminLogin: { username: string; password: string }; setAdminLogin: (v: { username: string; password: string }) => void; error: string; setError: (v: string) => void; onSuccess: () => void; onBack: () => void }) {
  return <div className="admin-login" dir={lang === 'ar' ? 'rtl' : 'ltr'}><div className="admin-login-aside"><div className="admin-login-tools"><LangSwitch lang={lang} setLang={setLang} /></div><button className="admin-wordmark" onClick={onBack}>second life<em>.</em></button><div><span className="admin-kicker">{copy(lang, 'استوديو خاص / ٠٤', 'Private studio / 04')}</span><h1>{copy(lang, <>أشياء جميلة،<br /><i>محفوظة جيداً.</i></>, <>Good things,<br /><i>well kept.</i></>)}</h1><p>{copy(lang, 'غرفة التحكم للقطع، الأشخاص والوعود خلف كل قائمة.', 'The control room for the pieces, people and promises behind every listing.')}</p></div><span className="admin-aside-foot">{copy(lang, 'بغداد · العراق · ٢٠٢٤', 'Baghdad · Iraq · 2024')}</span></div><form className="admin-login-form" onSubmit={(e) => { e.preventDefault(); if (adminLogin.username !== 'ADMIN2016' || adminLogin.password !== 'ADMIN2016') { setError(copy(lang, 'اسم المستخدم أو كلمة المرور غير صحيحة.', 'That username or password does not match our records.')); return; } setError(''); onSuccess(); }}><div className="admin-login-top"><button type="button" onClick={onBack}><ArrowLeft size={15} /> {copy(lang, 'العودة للمتجر', 'Back to storefront')}</button><span><LangSwitch lang={lang} setLang={setLang} /></span></div><div><span className="admin-kicker">{copy(lang, 'تسجيل دخول الاستوديو', 'Sign in to the studio')}</span><h2>{copy(lang, 'أهلاً بكِ.', 'Welcome in.')}</h2><p>{copy(lang, 'أديري المجموعة بعين هادئة للتفاصيل.', 'Manage the edit with a quiet eye for detail.')}</p></div><label>{copy(lang, 'اسم المستخدم', 'Username')}<input autoFocus value={adminLogin.username} onChange={(e) => setAdminLogin({ ...adminLogin, username: e.target.value })} /></label><label>{copy(lang, 'كلمة المرور', 'Password')}<input type="password" value={adminLogin.password} onChange={(e) => setAdminLogin({ ...adminLogin, password: e.target.value })} /></label>{error && <p className="admin-error">{error}</p>}<button className="admin-primary" type="submit">{copy(lang, 'دخول إلى غرفة التحكم', 'Enter control room')} <ArrowRight size={15} /></button><small className="admin-demo">{copy(lang, 'الوصول التجريبي متاح لهذه التجربة المحلية.', 'Demo access is enabled for this local experience.')}</small></form></div>;
}

function AdminDashboard({ lang, setLang, dark, setDark, active, setActive, submissions, setSubmissions, products, setProducts, orders, setOrders, users, reviewing, setReviewing, reviewPrice, setReviewPrice, rejectReason, setRejectReason, draft, setDraft, userDetail, setUserDetail, orderDetail, setOrderDetail, notify, onLogout }: { lang: Lang; setLang: (v: Lang) => void; dark: boolean; setDark: (v: boolean) => void; active: 'Overview' | 'Seller Submissions' | 'Catalog' | 'Orders' | 'Users'; setActive: (v: 'Overview' | 'Seller Submissions' | 'Catalog' | 'Orders' | 'Users') => void; submissions: Submission[]; setSubmissions: (v: Submission[]) => void; products: Product[]; setProducts: (v: Product[]) => void; orders: Order[]; setOrders: (v: Order[]) => void; users: User[]; reviewing: Submission | null; setReviewing: (v: Submission | null) => void; reviewPrice: string; setReviewPrice: (v: string) => void; rejectReason: string; setRejectReason: (v: string) => void; draft: Product | null; setDraft: (v: Product | null) => void; userDetail: User | null; setUserDetail: (v: User | null) => void; orderDetail: Order | null; setOrderDetail: (v: Order | null) => void; notify: (v: string) => void; onLogout: () => void }) {
  const pending = submissions.filter((s) => s.status === 'Pending Review').length; const nav: ('Overview' | 'Seller Submissions' | 'Catalog' | 'Orders' | 'Users')[] = ['Overview', 'Seller Submissions', 'Catalog', 'Orders', 'Users'];
  const label = (s: string) => lang === 'ar' ? ({ Overview: 'نظرة عامة', 'Seller Submissions': 'طلبات البائعات', Catalog: 'المجموعة', Orders: 'الطلبات', Users: 'العضوات' }[s] || s) : s;
  return <div className={`admin-shell ${dark ? 'admin-dark' : 'admin-light'}`} dir={lang === 'ar' ? 'rtl' : 'ltr'}><aside className="admin-sidebar"><div className="admin-side-tools"><LangSwitch lang={lang} setLang={setLang} /></div><button className="admin-brand" onClick={() => setActive('Overview')}>second life<em>.</em><small>STUDIO CONTROL</small></button><div className="admin-side-label">{copy(lang, 'مساحة العمل', 'Workspace')}</div><nav>{nav.map((item) => <button className={active === item ? 'active' : ''} key={item} onClick={() => setActive(item)}>{item === 'Overview' ? <LayoutDashboard size={17} /> : item === 'Seller Submissions' ? <Wallet size={17} /> : item === 'Catalog' ? <Package size={17} /> : item === 'Orders' ? <BarChart3 size={17} /> : <Users size={17} />}<span>{label(item)}</span>{item === 'Seller Submissions' && pending > 0 && <b className="nav-count">{pending}</b>}</button>)}</nav><div className="admin-side-bottom"><button onClick={() => setDark(!dark)}><Settings2 size={16} /> {dark ? copy(lang, 'خلفية فاتحة', 'Light canvas') : copy(lang, 'خلفية داكنة', 'Dark canvas')}</button><button onClick={onLogout}><LogIn size={16} /> {copy(lang, 'تسجيل الخروج', 'Sign out')}</button></div></aside><main className="admin-main"><header className="admin-header"><div><span className="admin-kicker">{copy(lang, 'الثلاثاء، ٢٨ مايو ٢٠٢٤', 'Tuesday, 28 May 2024')}</span><h1>{label(active)}</h1></div><div className="admin-header-actions"><LangSwitch lang={lang} setLang={setLang} /><span className="admin-live"><i /> {copy(lang, 'مساحة محلية', 'Local workspace')}</span><button className="admin-avatar">SL</button></div></header>{active === 'Overview' && <AdminOverview lang={lang} products={products} submissions={submissions} orders={orders} users={users} setActive={setActive} />}{active === 'Seller Submissions' && <AdminSubmissions lang={lang} submissions={submissions} setSubmissions={setSubmissions} reviewing={reviewing} setReviewing={setReviewing} reviewPrice={reviewPrice} setReviewPrice={setReviewPrice} rejectReason={rejectReason} setRejectReason={setRejectReason} products={products} setProducts={setProducts} notify={notify} />}{active === 'Catalog' && <AdminCatalog lang={lang} products={products} setProducts={setProducts} draft={draft} setDraft={setDraft} notify={notify} />}{active === 'Orders' && <AdminOrders lang={lang} orders={orders} setOrders={setOrders} detail={orderDetail} setDetail={setOrderDetail} />}{active === 'Users' && <AdminUsers lang={lang} users={users} orders={orders} submissions={submissions} detail={userDetail} setDetail={setUserDetail} />}</main></div>;
}

function AdminOverview({ lang, products, submissions, orders, users, setActive }: { lang: Lang; products: Product[]; submissions: Submission[]; orders: Order[]; users: User[]; setActive: (v: 'Overview' | 'Seller Submissions' | 'Catalog' | 'Orders' | 'Users') => void }) {
  const revenue = orders.filter((o) => o.status !== 'Cancelled').reduce((sum, o) => sum + o.total, 1640);
  const metrics = [{ label: copy(lang, 'إجمالي المبيعات', 'Total revenue'), value: priceFor(revenue, lang), change: copy(lang, '+١٢.٤٪ هذا الأسبوع', '+12.4% this week'), icon: CircleDollarSign }, { label: copy(lang, 'القطع النشطة', 'Active listings'), value: `${products.filter((p) => p.visible !== false && !p.soldOut).length}`, change: copy(lang, '+٣ هذا الأسبوع', '+3 this week'), icon: Package }, { label: copy(lang, 'بانتظار الاعتماد', 'Pending approvals'), value: `${submissions.filter((s) => s.status === 'Pending Review').length}`, change: copy(lang, 'تحتاج انتباهك', 'Needs attention'), icon: Upload }, { label: copy(lang, 'دفعات مكتملة', 'Completed payouts'), value: priceFor(2486, lang), change: copy(lang, '١٤ بائعة', '14 sellers'), icon: Wallet }, { label: copy(lang, 'العضوات المسجلات', 'Registered users'), value: `${users.length}`, change: copy(lang, '+٨.٢٪', '+8.2%'), icon: Users }];
  return <div className="admin-overview"><div className="admin-welcome"><div><span className="admin-kicker">{copy(lang, 'الأسبوع في حركة', 'The week in motion')}</span><h2>{copy(lang, <>اختيار جيد<br /><i>يستمر.</i></>, <>A good edit<br /><i>keeps moving.</i></>)}</h2></div><button className="admin-outline" onClick={() => setActive('Seller Submissions')}>{copy(lang, 'راجعي القطع', 'Review the edit')} <ArrowRight size={14} /></button></div><div className="metric-grid">{metrics.map(({ label, value, change, icon: Icon }) => <div className="metric-tile" key={label}><div className="metric-top"><span>{label}</span><Icon size={16} /></div><strong>{value}</strong><small className={change.includes('attention') || change.includes('انتباه') ? 'attention' : ''}>{change}</small></div>)}</div><div className="overview-grid"><div className="chart-panel"><div className="panel-heading"><div><span className="admin-kicker">{copy(lang, 'المبيعات الإجمالية', 'Gross sales')}</span><h3>{copy(lang, 'اتجاه المبيعات', 'Sales trend')}</h3></div><span className="chart-period">{copy(lang, 'آخر ٧ أشهر', 'Last 7 months')} <ChevronDown size={14} /></span></div><div className="sales-chart"><svg viewBox="0 0 640 230" preserveAspectRatio="none"><path d="M0 190 C60 166 75 178 120 145 S180 155 215 122 S280 142 322 108 S370 130 408 86 S465 105 500 71 S560 88 640 34" fill="none" stroke="currentColor" strokeWidth="3" /><path d="M0 190 C60 166 75 178 120 145 S180 155 215 122 S280 142 322 108 S370 130 408 86 S465 105 500 71 S560 88 640 34 V230 H0Z" fill="currentColor" opacity=".08" /></svg><div className="chart-x"><span>Dec</span><span>Jan</span><span>Feb</span><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span></div></div></div><div className="chart-panel submissions-chart"><div className="panel-heading"><div><span className="admin-kicker">{copy(lang, 'مسار البائعات', 'Seller pipeline')}</span><h3>{copy(lang, 'الطلبات', 'Submissions')}</h3></div><button className="panel-link" onClick={() => setActive('Seller Submissions')}>{copy(lang, 'عرض الكل', 'View all')}</button></div><div className="bar-chart">{['Pending', 'Approved', 'Listed', 'Sold'].map((label, i) => <div className="bar-item" key={label}><div className="bar-value">{[3, 5, 8, 4][i]}</div><div className={`bar bar-${i}`} style={{ height: `${[42, 66, 94, 57][i]}%` }} /><span>{lang === 'ar' ? ['معلّق', 'معتمد', 'معروض', 'مباع'][i] : label}</span></div>)}</div></div></div><div className="recent-panel"><div className="panel-heading"><div><span className="admin-kicker">{copy(lang, 'آخر حركة', 'Latest movement')}</span><h3>{copy(lang, 'الطلبات الأخيرة', 'Recent orders')}</h3></div><button className="panel-link" onClick={() => setActive('Orders')}>{copy(lang, 'كل الطلبات', 'See orders')}</button></div><div className="recent-list">{orders.slice(0, 3).map((o) => <div className="recent-row" key={o.id}><span className="order-dot" /><div><b>#{o.id}</b><small>{o.customer} · {o.date}</small></div><strong>{priceFor(o.total, lang)}</strong><span className={`status status-${o.status.toLowerCase()}`}>{lang === 'ar' ? ({ Processing: 'قيد التجهيز', Shipped: 'تم الشحن', Delivered: 'تم التسليم', Cancelled: 'ملغى' }[o.status]) : o.status}</span></div>)}</div></div></div>;
}

function AdminSubmissions({ lang, submissions, setSubmissions, reviewing, setReviewing, reviewPrice, setReviewPrice, rejectReason, setRejectReason, products, setProducts, notify }: { lang: Lang; submissions: Submission[]; setSubmissions: (v: Submission[]) => void; reviewing: Submission | null; setReviewing: (v: Submission | null) => void; reviewPrice: string; setReviewPrice: (v: string) => void; rejectReason: string; setRejectReason: (v: string) => void; products: Product[]; setProducts: (v: Product[]) => void; notify: (v: string) => void }) {
  const [filter, setFilter] = useState<SubmissionStatus | 'All'>('Pending Review'); const visible = submissions.filter((s) => filter === 'All' || s.status === filter);
  const approve = () => { if (!reviewing || !reviewPrice || Number(reviewPrice) <= 0) { notify(copy(lang, 'أضيفي سعر العرض قبل الاعتماد.', 'Add a listing price before approving.')); return; } const source = products[(reviewing.id + 1) % products.length] || seedProducts[0]; const p: Product = { ...source, id: Math.max(0, ...products.map((x) => x.id)) + 1, name: `${reviewing.designer} ${reviewing.item}`, designer: reviewing.designer, size: reviewing.size, price: Number(reviewPrice), original: Math.round(Number(reviewPrice) * 2.7), visible: true, soldOut: false }; setProducts([...products, p]); setSubmissions(submissions.map((s) => s.id === reviewing.id ? { ...s, status: 'Listed', listingPrice: Number(reviewPrice) } : s)); setReviewing(null); notify(copy(lang, 'تم اعتماد القطعة وإضافتها للمجموعة.', 'Approved and added to the storefront.')); };
  return <div className="admin-view"><div className="view-intro"><div><span className="admin-kicker">{copy(lang, 'غرفة البائعات', 'The seller room')}</span><p>{copy(lang, 'كل قطعة تبدأ بشخص وقصة وقليل من الثقة.', 'Every piece begins with a person, a story, and a little trust.')}</p></div><button className="admin-outline" onClick={() => setFilter('All')}>{copy(lang, 'عرض الكل', 'Show all')} <ArrowRight size={14} /></button></div><div className="filter-tabs">{(['Pending Review', 'Approved', 'Rejected', 'Listed', 'Sold'] as SubmissionStatus[]).map((status) => <button className={filter === status ? 'active' : ''} key={status} onClick={() => setFilter(status)}>{lang === 'ar' ? ({ 'Pending Review': 'بانتظار المراجعة', Approved: 'معتمد', Rejected: 'مرفوض', Listed: 'معروض', Sold: 'مباع' }[status]) : status}<span>{submissions.filter((s) => s.status === status).length}</span></button>)}</div><div className="data-panel"><div className="table-head"><span>{copy(lang, 'القطعة / البائعة', 'Piece / seller')}</span><span>{copy(lang, 'تاريخ الإرسال', 'Submitted')}</span><span>{copy(lang, 'العائد المطلوب', 'Requested payout')}</span><span>{copy(lang, 'الحالة', 'Status')}</span><span /></div>{visible.map((s) => <div className="table-row submission-row" key={s.id}><div className="piece-cell"><div className="submission-thumb"><img src={asset(seedProducts[s.id % seedProducts.length].image)} alt="" /></div><div><b>{s.designer}</b><small>{s.item} · {s.size}</small></div></div><span className="muted-cell">28 May 2024</span><strong>{priceFor(s.requestedPayout, lang)}</strong><span className={`status status-${s.status.toLowerCase().replace(' ', '-')}`}>{lang === 'ar' ? ({ 'Pending Review': 'بانتظار المراجعة', Approved: 'معتمد', Rejected: 'مرفوض', Listed: 'معروض', Sold: 'مباع' }[s.status]) : s.status}</span><button className="row-action" onClick={() => { setReviewing(s); setReviewPrice(`${s.listingPrice || ''}`); }}><Eye size={16} /></button></div>)}</div>{reviewing && <div className="admin-modal-backdrop" onClick={() => setReviewing(null)}><div className="admin-modal review-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={() => setReviewing(null)}><X size={18} /></button><span className="admin-kicker">Submission #{reviewing.id}</span><h2>{reviewing.designer}<br /><i>{reviewing.item}</i></h2><div className="review-images">{[0, 1, 2, 3].map((i) => <div className="review-image" key={i}><img src={asset(seedProducts[(reviewing.id + i) % seedProducts.length].image)} alt="" /></div>)}</div><div className="review-details"><div><span className="admin-kicker">{copy(lang, 'ملاحظات البائعة', 'Seller notes')}</span><p>{reviewing.notes || copy(lang, 'لا توجد ملاحظات.', 'No notes provided.')}</p><div className="review-meta"><span>{copy(lang, 'المقاس', 'Size')}<b>{reviewing.size}</b></span><span>{copy(lang, 'المطلوب', 'Requested')}<b>{priceFor(reviewing.requestedPayout, lang)}</b></span></div></div><div className="review-action-box"><label>{copy(lang, 'سعر العرض', 'Listing price')}<input type="number" value={reviewPrice} onChange={(e) => setReviewPrice(e.target.value)} /></label><button className="admin-primary" onClick={approve}>{copy(lang, 'اعتماد وعرض', 'Approve & list')} <Check size={15} /></button><div className="reject-line"><input placeholder={copy(lang, 'سبب الرفض', 'Reason for rejection')} value={rejectReason} onChange={(e) => setRejectReason(e.target.value)} /><button className="admin-danger" onClick={() => { if (!rejectReason.trim()) return notify(copy(lang, 'أضيفي سبباً قبل الرفض.', 'Add a reason before rejecting.')); setSubmissions(submissions.map((s) => s.id === reviewing.id ? { ...s, status: 'Rejected', rejectionReason: rejectReason } : s)); setReviewing(null); notify(copy(lang, 'تم إشعار البائعة.', 'Seller notified.')); }}> {copy(lang, 'رفض', 'Reject')}</button></div></div></div></div></div>}</div>;
}

function AdminCatalog({ lang, products, setProducts, draft, setDraft, notify }: { lang: Lang; products: Product[]; setProducts: (v: Product[]) => void; draft: Product | null; setDraft: (v: Product | null) => void; notify: (v: string) => void }) {
  const empty: Product = { id: 0, name: '', designer: '', category: categories[0], size: 'UK 10', condition: 'Excellent', conditionNotes: '', price: 0, original: 0, image: seedProducts[0].image, gallery: [seedProducts[0].image], fabric: '', color: '', details: '', visible: true };
  return <div className="admin-view"><div className="view-intro"><div><span className="admin-kicker">{copy(lang, 'تنسيق المجموعة', 'Merchandising')}</span><p>{copy(lang, 'حافظي على أرضية المتجر دقيقة وحية وجديرة بالثقة.', 'Keep the shop floor precise, alive and easy to trust.')}</p></div><button className="admin-primary" onClick={() => setDraft(empty)}><Plus size={15} /> {copy(lang, 'إضافة قطعة', 'Add a listing')}</button></div><div className="catalog-grid">{products.map((p) => <div className={`catalog-card ${p.visible === false ? 'is-hidden' : ''}`} key={p.id}><div className="catalog-image"><img src={asset(p.image)} alt="" /><span>{p.visible === false ? copy(lang, 'مخفية', 'Hidden') : p.soldOut ? copy(lang, 'مباعة', 'Sold out') : copy(lang, 'حية', 'Live')}</span></div><div className="catalog-card-copy"><div><span className="admin-kicker">{displayCategory(p.category, lang)}</span><h3>{displayName(p, lang)}</h3><p>{p.designer} · {p.size}</p></div><strong>{priceFor(p.price, lang)}</strong></div><div className="catalog-actions"><button onClick={() => setProducts(products.map((x) => x.id === p.id ? { ...x, visible: x.visible === false } : x))}>{p.visible === false ? <Eye size={14} /> : <EyeOff size={14} />}</button><button onClick={() => setProducts(products.map((x) => x.id === p.id ? { ...x, soldOut: !x.soldOut } : x))}>{p.soldOut ? copy(lang, 'إعادة العرض', 'Restock') : copy(lang, 'بيع القطعة', 'Mark sold')}</button><button onClick={() => setDraft(p)}><Pencil size={14} /> {copy(lang, 'تعديل', 'Edit')}</button><button className="catalog-delete" onClick={() => { if (window.confirm(copy(lang, 'إزالة هذه القطعة؟', 'Remove this listing?'))) { setProducts(products.filter((x) => x.id !== p.id)); notify(copy(lang, 'تمت إزالة القطعة.', 'Listing removed.')); } }}><Trash2 size={14} /></button></div></div>)}</div>{draft && <div className="admin-modal-backdrop" onClick={() => setDraft(null)}><div className="admin-modal catalog-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={() => setDraft(null)}><X size={18} /></button><span className="admin-kicker">{draft.id ? copy(lang, 'تعديل قطعة', 'Edit listing') : copy(lang, 'قطعة جديدة', 'New listing')}</span><h2>{draft.id ? copy(lang, 'نصقل الاختيار.', 'Refine the edit.') : copy(lang, 'أضيفي إلى المجموعة.', 'Add to the edit.')}</h2><div className="catalog-form">{([['name', copy(lang, 'الاسم', 'Name')], ['designer', copy(lang, 'المصمم', 'Designer')], ['category', copy(lang, 'التصنيف', 'Category')], ['size', copy(lang, 'المقاس', 'Size')], ['price', copy(lang, 'السعر', 'Price')], ['original', copy(lang, 'السعر الأصلي', 'Original price')]] as const).map(([key, label]) => <label key={key}>{label}{key === 'category' ? <select value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value })}>{categories.map((c) => <option key={c}>{c}</option>)}</select> : <input type={key === 'price' || key === 'original' ? 'number' : 'text'} value={draft[key]} onChange={(e) => setDraft({ ...draft, [key]: key === 'price' || key === 'original' ? Number(e.target.value) : e.target.value } as Product)} />}</label>)}</div><button className="admin-primary modal-save" onClick={() => { if (!draft.name || !draft.designer || !draft.price) return notify(copy(lang, 'أكملي الاسم والمصمم والسعر.', 'Complete the name, designer and price.')); setProducts(draft.id ? products.map((p) => p.id === draft.id ? draft : p) : [...products, { ...draft, id: Math.max(0, ...products.map((p) => p.id)) + 1 }]); setDraft(null); notify(copy(lang, 'تم تحديث المجموعة.', 'Catalog updated.')); }}>{copy(lang, 'حفظ القطعة', 'Save listing')} <Check size={15} /></button></div></div>}</div>;
}

function AdminOrders({ lang, orders, setOrders, detail, setDetail }: { lang: Lang; orders: Order[]; setOrders: (v: Order[]) => void; detail: Order | null; setDetail: (v: Order | null) => void }) {
  const statusText = (status: Order['status']) => lang === 'ar' ? ({ Processing: 'قيد التجهيز', Shipped: 'تم الشحن', Delivered: 'تم التسليم', Cancelled: 'ملغى' }[status]) : status;
  return <div className="admin-view"><div className="view-intro"><div><span className="admin-kicker">{copy(lang, 'مكتب التوصيل', 'Fulfilment desk')}</span><p>{copy(lang, 'تسليم هادئ واحداً تلو الآخر، من الدفع إلى الباب.', 'One calm handoff at a time, from checkout to doorstep.')}</p></div></div><div className="data-panel"><div className="table-head order-head"><span>{copy(lang, 'الطلب', 'Order')}</span><span>{copy(lang, 'العميلة', 'Customer')}</span><span>{copy(lang, 'التاريخ', 'Placed')}</span><span>{copy(lang, 'المجموع', 'Total')}</span><span>{copy(lang, 'الحالة', 'Status')}</span><span /></div>{orders.map((o) => <div className="table-row order-row" key={o.id}><b>#{o.id}</b><div><strong>{o.customer}</strong><small>{o.phone}</small></div><span className="muted-cell">{o.date}</span><strong>{priceFor(o.total, lang)}</strong><select value={o.status} onChange={(e) => setOrders(orders.map((x) => x.id === o.id ? { ...x, status: e.target.value as Order['status'] } : x))}>{(['Processing', 'Shipped', 'Delivered', 'Cancelled'] as const).map((s) => <option key={s} value={s}>{statusText(s)}</option>)}</select><button className="row-action" onClick={() => setDetail(o)}><ChevronRight size={16} /></button></div>)}</div>{detail && <div className="admin-modal-backdrop" onClick={() => setDetail(null)}><div className="admin-modal order-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={() => setDetail(null)}><X size={18} /></button><span className="admin-kicker">Order #{detail.id}</span><h2>{copy(lang, 'تفاصيل التوصيل.', 'Delivery details.')}</h2><div className="order-detail-grid"><div><span className="admin-kicker">{copy(lang, 'العميلة', 'Customer')}</span><b>{detail.customer}</b><span>{detail.phone}</span><span>{detail.email}</span></div><div><span className="admin-kicker">{copy(lang, 'العنوان', 'Address')}</span><b>{detail.address}</b></div></div><div className="order-items">{detail.items.map((line) => <div key={line.product.id}><img src={asset(line.product.image)} alt="" /><span>{displayName(line.product, lang)}<small>{line.product.designer} · Qty {line.quantity}</small></span><b>{priceFor(line.product.price * line.quantity, lang)}</b></div>)}</div><div className="order-total"><span>{copy(lang, 'المجموع', 'Total')}</span><b>{priceFor(detail.total, lang)}</b></div></div></div>}</div>;
}

function AdminUsers({ lang, users, orders, submissions, detail, setDetail }: { lang: Lang; users: User[]; orders: Order[]; submissions: Submission[]; detail: User | null; setDetail: (v: User | null) => void }) {
  return <div className="admin-view"><div className="view-intro"><div><span className="admin-kicker">{copy(lang, 'سجل المجتمع', 'Community ledger')}</span><p>{copy(lang, 'نساء يشترين بوعي، يبعن بأمانة ويعدن للفصل القادم.', 'People who buy thoughtfully, sell honestly and return for the next chapter.')}</p></div></div><div className="data-panel"><div className="table-head user-head"><span>{copy(lang, 'العضوة', 'Member')}</span><span>{copy(lang, 'الهاتف', 'Phone')}</span><span>{copy(lang, 'الطلبات', 'Orders')}</span><span>{copy(lang, 'نشاط البيع', 'Consignment')}</span><span /></div>{users.map((u) => <div className="table-row user-row" key={u.id}><div className="user-cell"><span className="admin-user-avatar">{u.name.slice(0, 1)}</span><div><b>{u.name}</b><small>{u.email || copy(lang, 'بلا بريد', 'No email')}</small></div></div><span className="muted-cell phone-cell">{u.phone}</span><strong>{u.orders.length}</strong><span>{u.submissions.length}</span><button className="row-action" onClick={() => setDetail(u)}><ChevronRight size={16} /></button></div>)}</div>{detail && <div className="admin-modal-backdrop" onClick={() => setDetail(null)}><div className="admin-modal user-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={() => setDetail(null)}><X size={18} /></button><div className="user-detail-head"><span className="admin-user-avatar large">{detail.name.slice(0, 1)}</span><div><span className="admin-kicker">Member #{detail.id}</span><h2>{detail.name}</h2><p>{detail.phone}</p></div></div><div className="user-detail-stats"><div><b>{detail.orders.length}</b><span>{copy(lang, 'طلبات', 'orders')}</span></div><div><b>{detail.submissions.length}</b><span>{copy(lang, 'طلبات بيع', 'submissions')}</span></div><div><b>{priceFor(orders.filter((o) => detail.orders.includes(o.id)).reduce((sum, o) => sum + o.total, 0), lang)}</b><span>{copy(lang, 'منفق', 'spent')}</span></div></div><div className="user-history"><div><span className="admin-kicker">{copy(lang, 'تاريخ الطلبات', 'Order history')}</span>{orders.filter((o) => detail.orders.includes(o.id)).map((o) => <p key={o.id}>#{o.id}<b>{priceFor(o.total, lang)}</b></p>)}</div><div><span className="admin-kicker">{copy(lang, 'نشاط البيع', 'Consignment activity')}</span>{submissions.filter((s) => detail.submissions.includes(s.id)).map((s) => <p key={s.id}>{s.designer}<span className="status">{s.status}</span></p>)}</div></div></div></div>}</div>;
}

export default App;